mapper.select:
select count(1) from sup_equipment_cabinet
where room_id = #{roomId}
  and cabinet_no = #{cabinetNo}

  and cabinet_id <> #{cabinetId}

mapper.update:
update sup_hardware_asset
set equipment_room = null, cabinet_no = null, rack_u_start = null, rack_u_end = null
where site_id = #{siteId} and equipment_room = #{roomName}

update sup_server
set equipment_room = null, cabinet_no = null, rack_u_start = null, rack_u_end = null
where site_id = #{siteId} and equipment_room = #{roomName}

mapper.select:
select count(1) from sup_hardware_asset
where site_id = #{siteId}
  and equipment_room = #{roomName}
  and cabinet_no = #{cabinetNo}
  and rack_u_start <= #{rackUEnd}
  and rack_u_end >= #{rackUStart}

  and asset_id <> #{excludeAssetId}

select count(1) from sup_server
where site_id = #{siteId}
  and equipment_room = #{roomName}
  and cabinet_no = #{cabinetNo}
  and rack_u_start <= #{rackUEnd}
  and rack_u_end >= #{rackUStart}

  and server_id <> #{excludeServerId}
